var app = WebApplication.Create(args);

app.MapPost("/orders/{id:guid}/cancel", async (Guid id, Orders orders) =>
{
    long version = await orders.CancelAsync(id); // version of this write
    // The customer's own change, in the words the product team chose
    return Results.Accepted($"/orders/{id}?seen={version}",
        new { id, status = "Cancelled", refund = "Within 5 days", version });
});

app.MapGet("/orders/{id:guid}", async (Guid id, long? seen, OrderViews views) =>
{
    var view = await views.FindAsync(id);
    // Never show this customer a state older than one they caused
    if (view is null || view.Version < (seen ?? 0))
        return Results.Ok(new { id, status = "Updating" });
    return Results.Ok(view);
});

app.Run();
